#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/.bak-step156-$TS"
echo "==> step156: inventory bulk hide/unhide + note (#8)"
echo "    backup: $BK"
mkdir -p "$BK/routes" "$BK/views/admin"
cp "$GSZ/routes/adminInventory.js"           "$BK/routes/"       2>/dev/null || true
cp "$GSZ/views/admin/inventory_manage.ejs"   "$BK/views/admin/"  2>/dev/null || true

restore(){ echo "!! error — restoring"; cp "$BK/routes/adminInventory.js" "$GSZ/routes/" 2>/dev/null || true; cp "$BK/views/admin/inventory_manage.ejs" "$GSZ/views/admin/" 2>/dev/null || true; }
trap 'restore' ERR

echo "==> migration: inventory_items.note column"
NODE_PATH="$GSZ/node_modules" node -e "
require('dotenv').config({path:'$GSZ/.env'});
const { Pool } = require('pg');
const p = new Pool({ host:process.env.DB_HOST, port:process.env.DB_PORT, database:process.env.DB_NAME, user:process.env.DB_USER, password:process.env.DB_PASS });
p.query('ALTER TABLE inventory_items ADD COLUMN IF NOT EXISTS note text').then(()=>{ console.log('    note column ready'); return p.end(); }).catch(e=>{ console.error('    migration failed: '+e.message); process.exit(1); });
"

PATCHER=$(mktemp /tmp/patch_step156.XXXXXX.js)
echo "" | base64 -d > "$PATCHER"
echo "==> applying route patches"
NODE_PATH="$GSZ/node_modules" node "$PATCHER" "$GSZ"

echo "==> writing new manage view"
VTMP=$(mktemp /tmp/invmanage.XXXXXX.ejs)
echo "" | base64 -d > "$VTMP"
NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$VTMP','utf8'),{filename:'$VTMP',compileDebug:false});console.log('    new manage view compiles')"
mv "$VTMP" "$GSZ/views/admin/inventory_manage.ejs"

echo "==> validating"
node --check "$GSZ/routes/adminInventory.js"
NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$GSZ/views/admin/inventory_manage.ejs','utf8'),{filename:'$GSZ/views/admin/inventory_manage.ejs'});console.log('    ejs ok')"

echo "==> restarting"
pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000
for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE after ${i}s"; false; }
echo "    homepage 200: OK (after ${i}s)"

rm -f "$PATCHER"
trap - ERR
echo ""
echo "==> step156 OK  Inventory manage now has bulk Hide (hold a unit out of auto-delivery), Unhide, and Set-note — plus per-unit Hide/Unhide and a note field in Edit. Held units show their own tile + filter and never auto-deliver or count as available. (Delete/Move/Edit also work on held units.)"
